488:    * Used to assess acute malnutrition (wasting).
489:    * @param height - Patient's height/length in centimeters (valid range: 45-110 cm). Numeric strings are accepted.
490:    * @param weight - Patient's weight in kilograms
491:    * @returns Z-score as a string (e.g., '-2', '0', '1'), or null if out of range, reference missing, or inputs missing
492:    */
493:   calcWeightForHeightZscore = (height: number | string, weight: number): string | null => {
494:     const numericHeight = Number(height);
